"use client";

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import { useId, type MouseEvent as ReactMouseEvent } from "react";

/** The same plate-scale canvas as the reference footer graphic. */
const VIEWBOX_WIDTH = 1410;
const VIEWBOX_HEIGHT = 258;
const CELL_HEIGHT = 48;
const TRACKING = 1;
const SPRING = { stiffness: 150, damping: 25 } as const;

/**
 * Five-row orthogonal glyphs, cut lowercase. The cells are only a layout
 * source. At render time, adjacent cells share edges, so the SVG draws one
 * clean outline instead of a stack of rounded rectangles.
 *
 * Row one is the ascender line and rows two to five are the x-height, so `d`
 * and `h` stand a row above everything else — which is the whole of what makes
 * a word read as lowercase rather than as small capitals. The `2` uses all
 * five rows: its diagonal must stay legible at footer scale.
 */
const GLYPHS: Readonly<Record<string, readonly string[]>> = {
  a: [".....", ".####", "#...#", "#...#", ".####"],
  d: ["....#", ".####", "#...#", "#...#", ".####"],
  h: ["#....", "#####", "#...#", "#...#", "#...#"],
  m: [".....", "#####", "#.#.#", "#.#.#", "#.#.#"],
  r: [".....", "#.###", "##...", "#....", "#...."],
  s: [".....", ".####", "##...", "...##", "####."],
  u: [".....", "#...#", "#...#", "#...#", ".####"],
  v: [".....", "#...#", "#...#", ".#.#.", "..#.."],
  "2": ["#####", "....#", "#####", "#....", "#####"],
};

type Cell = { x: number; y: number };

function layout(text: string) {
  const cells: Cell[] = [];
  let cursor = 0;

  for (const char of text) {
    const glyph = GLYPHS[char];
    if (!glyph) continue;

    for (let y = 0; y < glyph.length; y++) {
      for (let x = 0; x < glyph[y].length; x++) {
        if (glyph[y][x] === "#") cells.push({ x: cursor + x, y });
      }
    }

    cursor += glyph[0].length + TRACKING;
  }

  return {
    cells,
    columns: Math.max(cursor - TRACKING, 1),
  };
}

function formatCoordinate(value: number) {
  return value.toFixed(3).replace(/\.?(0+)$/, "");
}

function buildPaths(cells: Cell[], columns: number) {
  const cellWidth = (VIEWBOX_WIDTH - 2) / columns;
  const occupied = new Set(cells.map((cell) => `${cell.x}:${cell.y}`));
  const fill: string[] = [];
  const outline: string[] = [];

  for (const cell of cells) {
    const x0 = 1 + cell.x * cellWidth;
    const x1 = 1 + (cell.x + 1) * cellWidth;
    const y0 = 1 + cell.y * CELL_HEIGHT;
    const y1 = y0 + CELL_HEIGHT;
    const x = formatCoordinate(x0);
    const right = formatCoordinate(x1);
    const y = formatCoordinate(y0);
    const bottom = formatCoordinate(y1);

    fill.push(`M${x} ${y}H${right}V${bottom}H${x}Z`);

    if (!occupied.has(`${cell.x}:${cell.y - 1}`)) {
      outline.push(`M${x} ${y}H${right}`);
    }
    if (!occupied.has(`${cell.x + 1}:${cell.y}`)) {
      outline.push(`M${right} ${y}V${bottom}`);
    }
    if (!occupied.has(`${cell.x}:${cell.y + 1}`)) {
      outline.push(`M${right} ${bottom}H${x}`);
    }
    if (!occupied.has(`${cell.x - 1}:${cell.y}`)) {
      outline.push(`M${x} ${bottom}V${y}`);
    }
  }

  return { fill: fill.join(""), outline: outline.join("") };
}

export function SiteWordmark({
  text,
  className,
}: {
  text: string;
  className?: string;
}) {
  const id = useId().replace(/[^a-zA-Z0-9-]/g, "");
  const gradientId = `${id}-gradient`;
  const reduced = useReducedMotion();
  const ratio = useMotionValue(0.5);
  const gradientX1 = useSpring(
    useTransform(ratio, [0, 1], [0, VIEWBOX_WIDTH]),
    SPRING,
  );
  const { cells, columns } = layout(text);
  const paths = buildPaths(cells, columns);

  const handleMouseMove = (event: ReactMouseEvent<HTMLDivElement>) => {
    if (reduced) return;

    const rect = event.currentTarget.getBoundingClientRect();
    if (rect.width === 0) return;

    ratio.set((event.clientX - rect.left) / rect.width);
  };

  return (
    <div
      className={`screen-line-bottom after:z-1 after:bg-foreground/15 ${className ?? ""}`}
    >
      <div
        className="overflow-hidden"
        onMouseMove={handleMouseMove}
        onMouseLeave={() => ratio.set(0.5)}
      >
        {/* The mark half-bleeds off the bottom of the page. Lowercase sits a
            row lower in the cell grid than the capitals did, so the bleed is
            pulled back to a quarter — otherwise the x-height letters go under
            the edge and only the two ascenders are left standing. */}
        <div className="flex w-full translate-y-[25%] items-center justify-center">
          <svg
            aria-hidden
            className="mx-auto block h-auto w-full max-w-[1410px]"
            viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d={paths.fill}
              fill={`url(#${gradientId})`}
              fillRule="nonzero"
            />
            <path
              d={paths.outline}
              className="stroke-foreground/10"
              strokeWidth="2"
              strokeLinecap="square"
              strokeLinejoin="miter"
              vectorEffect="non-scaling-stroke"
            />
            <defs>
              <motion.linearGradient
                id={gradientId}
                x1={gradientX1}
                y1="1"
                x2="705"
                y2="257"
                gradientUnits="userSpaceOnUse"
              >
                <stop
                  offset="0.625"
                  stopColor="var(--foreground)"
                  stopOpacity="0"
                />
                <stop offset="1" stopColor="var(--foreground)" />
              </motion.linearGradient>
            </defs>
          </svg>
        </div>
      </div>
    </div>
  );
}
import { Rss, SOCIAL_ICONS } from "@/components/icons";
import { SiteWordmark } from "@/components/site-wordmark";
import { site } from "@/lib/site";

/**
 * The profiles, minus the mailbox.
 *
 * The overview's "say hi" row is the directory — it is the place that answers
 * "how do I reach this person", so it carries every way, email included. The
 * footer is a signature, and a signature does not repeat the directory: it
 * carries the three places the work lives, and the feed, which is a property
 * of the site rather than of the person and so belongs here and nowhere else.
 */
const FOOTER_SOCIALS = site.socials.filter(
  (social) => !social.href.startsWith("mailto:"),
);

export function SiteFooter() {
  return (
    <footer className="max-w-screen overflow-x-clip px-2">
      <div className="mx-auto border-x border-line md:max-w-3xl">
        <div className="screen-line-top screen-line-bottom">
          <div className="stripe-divider h-12" />
        </div>

        {/* One closing line: the copyright reads left, the glyphs read right,
            and on a phone they stack centred rather than squeezing. */}
        <div className="screen-line-top screen-line-bottom flex flex-col items-center justify-center gap-x-4 gap-y-3 px-4 py-3 text-sm text-muted-foreground sm:flex-row sm:justify-between">
          {/* The mark, not the legal name: the wordmark below signs the page
              and this line should agree with it. */}
          <span>
            &copy; {new Date().getFullYear()} {site.handle.toLowerCase()}.
          </span>

          {/* Four glyphs on one gutter. The rules that used to stand between
              them were 16px of hairline at 12px intervals — texture, at this
              size, not structure. */}
          <nav aria-label="Elsewhere" className="flex items-center gap-4">
            {FOOTER_SOCIALS.map((social) => {
              const Glyph = SOCIAL_ICONS[social.label];
              return (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.label}
                  title={social.label}
                  className="flex items-center transition-colors hover:text-foreground"
                >
                  <Glyph className="size-4" />
                </a>
              );
            })}
            <a
              href={site.rssPath}
              aria-label="RSS feed"
              title="RSS feed — paste this address into a feed reader"
              className="flex items-center transition-colors hover:text-foreground"
            >
              <Rss className="size-4" />
            </a>
          </nav>
        </div>

      </div>

      <SiteWordmark text={site.handle.toLowerCase()} className="text-foreground" />

      <div aria-hidden className="h-(--fade-bottom-height)" />

      <div className="pb-[env(safe-area-inset-bottom,0)]" />
    </footer>
  );
}
